/**
 * The shared transcript-region content: optional header (the review page's
 * outcome banner), the waiting banner, error/loading/empty states, the
 * folded turn list (with the native "load earlier" affordance above it when
 * the host holds older messages) and the "滑到最新" pill. Callers own their scroll region and the tail
 * hook; this is pure rendering, so every live session surface looks and
 * behaves identically.
 */
export function SessionTranscript({ turns, error, atBottom, jumpToBottom, waiting, hasMore, loadingEarlier, pageError, pageUnsupported, onLoadEarlier, before, onRetry, sessionId, controller, prefs }: {
  turns: readonly TranscriptTurn[] | undefined
  error: boolean
  atBottom: boolean
  jumpToBottom: () => void
  waiting?: PendingInteractionKind
  /** The host holds messages older than the loaded window. */
  hasMore?: boolean
  /** An earlier page is being fetched right now. */
  loadingEarlier?: boolean
  /** The last earlier-page read failed (the button stays — tapping retries). */
  pageError?: boolean
  /** The deployment serves no page endpoint (the button goes away — retrying is pointless). */
  pageUnsupported?: boolean
  /** Prepend one earlier page above the window (the native grammar). */
  onLoadEarlier?: () => void
  /** Optional header content inside the region (the review page's outcome banner). */
  before?: ReactNode
  /** Re-read the tail (the error state's retry — a timeout/unavailable read
   *  must never be a dead end; the caller wires this to the hook's reload). */
  onRetry?: () => void
  /** The session the tail belongs to + the controller (message images read
   *  their bytes through the official attachment RPC; absent = refs only). */
  sessionId?: string
  controller?: BoardController
  /** 工作步骤的折法（三件事都来自官方设置；读不到时是产品默认）。 */
  prefs: WorkStepsPrefs
}) {
  /* 读者点开的折：**这一屏的选择**，不是会话数据。放在这里而不是每一轮各自存，
     是因为它们必须活过「重新读一次尾窗口」（重读会换掉整个轮列表的引用）。 */
  const [openTurns, setOpenTurns] = useState<ReadonlySet<string>>(() => new Set())
  const toggleTurn = useCallback((key: string): void => {
    setOpenTurns(previous => {
      const next = new Set(previous)
      if (next.has(key)) next.delete(key)
      else next.add(key)
      return next
    })
  }, [])
  /* 轮里每一组过程的小折（官方 `ProcessGroup` 那一级）。也是**这一屏的选择**：
     重新读一次尾窗口不该把读者点开的组又合上。 */
  const [collapsedGroups, setcollapsedGroups] = useState<ReadonlySet<string>>(() => new Set())
  const toggleGroup = useCallback((key: string): void => {
    setcollapsedGroups(previous => {
      const next = new Set(previous)
      if (next.has(key)) next.delete(key)
      else next.add(key)
      return next
    })
  }, [])
  /* 「加载更早」这一行只属于**不封顶**的表面：封顶的尾窗口是一段预览，不是日志。 */
  const paging = hasMore === true && onLoadEarlier !== undefined && pageUnsupported !== true
  const pagingDead = hasMore === true && pageUnsupported === true
  return (
    <>
      {before}
      <SessionWaitingNotice waiting={waiting} />
      {paging && (
        <div className={css.transcriptEarlierRow}>
          <Button size="sm" disabled={loadingEarlier === true} onClick={onLoadEarlier}>
            {t(loadingEarlier === true ? 'review.loadingEarlierBusy' : 'review.loadEarlier')}
          </Button>
          {pageError === true && (
            <p className={css.detailHint}>{t('review.loadEarlierFailed')}</p>
          )}
        </div>
      )}
      {pagingDead && (
        <div className={css.transcriptEarlierRow}>
          <p className={css.detailHint}>{t('review.loadEarlierUnsupported')}</p>
        </div>
      )}
      {error ? (
        <div className={css.transcriptErrorRow}>
          <p className={css.detailText}>{t('review.transcriptUnavailable')}</p>
          {onRetry !== undefined && (
            <Button size="sm" onClick={onRetry}>{t('review.retry')}</Button>
          )}
        </div>
      ) : turns === undefined ? (
        <p className={css.detailText}>{t('review.loading')}</p>
      ) : turns.length === 0 ? (
        <p className={css.detailText}>{t('review.transcriptEmpty')}</p>
      ) : (
        <TurnList
          turns={turns}
          prefs={prefs}
          sessionId={sessionId}
          controller={controller}
          openTurns={openTurns}
          onToggle={toggleTurn}
          collapsedGroups={collapsedGroups}
          onToggleGroup={toggleGroup}
        />
      )}
      <JumpToLatest atBottom={atBottom} onJump={jumpToBottom} />
    </>
  )
}

/** One waiting banner, shared by every session surface. */

/** The waiting notice: one neutral framed row + a warn chip carrying the
 *  semantics, so the banner is not a per-surface amber bar. It lived in the
 *  design system until it turned out to have exactly one user — this file — and
 *  one user is not sharing, so it lives beside the thing it draws. */
function Notice({ chip, children }: { chip: ReactNode; children: ReactNode }) {
  return (
    <div className={css.waitingNotice} role="status">
      <Chip kind="warn" fill={false}>{chip}</Chip>
      <span>{children}</span>
    </div>
  )
}
export function SessionWaitingNotice({ waiting }: { waiting: PendingInteractionKind | undefined }) {
  if (waiting === undefined) return null
  return (
    <Notice chip={t('review.waiting')}>
      {t('review.waitingTitle', { kind: t(waitingKeyOf(waiting)) })}
    </Notice>
  )
}

/**
 * The session's real workspace + composed Agent: read-only value rows INSIDE
 * the live config grid (the same row grammar as the model/effort/permission
 * selects, same field order as the task detail's 运行配置) — one module,
 * no separate facts strip, no explanatory paragraph. A value row renders in
 * the same box geometry as a select, so the read-only meaning is carried by
 * the absence of a dropdown affordance, never by prose.
 */
export function SessionFacts({ info, agentPresets = [] }: {
  info: { cwd?: string; agentPreset?: string } | undefined
  agentPresets?: readonly AgentPresetLabelSource[]
}) {
  if (info === undefined) return null
  const agentPreset = agentPresetLabelOf(info.agentPreset, agentPresets)
  return (
    <>
      <span className={css.reviewConfigRow}>
        <span className={`${css.reviewConfigLabel} ${components.truncate}`}>{t('review.sessionWorkspace')}</span>
        <span className={`${css.reviewConfigValue} ${components.truncate}`} title={info.cwd ?? undefined}>
          {info.cwd !== undefined ? workspaceLabelOf(info.cwd) : t('review.sessionUnknown')}
        </span>
      </span>
      <span className={css.reviewConfigRow}>
        <span className={`${css.reviewConfigLabel} ${components.truncate}`}>{t('review.sessionAgent')}</span>
        <span className={`${css.reviewConfigValue} ${components.truncate}`} title={agentPreset}>
          {agentPreset ?? t('review.sessionDefaultAgent')}
        </span>
      </span>
    </>
  )
}

/** Sum of the transcript's token accounting (the meter's fallback strip). */
interface SessionUsage {
  inputTokens: number
  outputTokens: number
  cacheReadTokens?: number
  cacheWriteTokens?: number
  reasoningTokens?: number
}

/**
 * The context meter block: native occupancy figure + colored composition
 * bar (from the transcript projections), the cumulative whole-log token
 * totals (from the `tokenUsage` projection — durable, not the paged-window
 * sum below), the whole-log turn/step figures (from `sessionStats`), or the
 * token-sum fallback strip when no projection is served. A high-occupancy
 * state (>= 85%) shifts the reading to the attention tone — the same warn
 * grammar as every board signal.
 */
export function ContextMeterPanel({ projections, usage }: {
  projections: TranscriptProjectionsShape | undefined
  usage: SessionUsage | undefined
}) {
  const occupancy = contextOccupancy(projections?.contextPressure)
  const segments = occupancy !== undefined
    ? contextSegments(occupancy, projections?.contextBreakdown)
    : undefined
  // Cumulative whole-log totals ride the projection; the paged-window sum is
  // only the fallback when the meter package is absent.
  const total = projections?.tokenUsage !== undefined
    ? {
      inputTokens: projections.tokenUsage.uncachedInputTokens,
      outputTokens: projections.tokenUsage.outputTokens,
      cacheReadTokens: projections.tokenUsage.cacheReadTokens,
      cacheWriteTokens: projections.tokenUsage.cacheWriteTokens,
    }
    : usage
  const totalCumulative = projections?.tokenUsage !== undefined
  if (occupancy !== undefined && segments !== undefined) {
    const warn = occupancy.percent >= 85
    return (
      <div
        className={css.reviewContextMeter}
        data-warn={warn ? '' : undefined}
        aria-label={t('review.meterOf', { percent: `${occupancy.percent}%` })}
      >
        <div className={css.reviewMeterHead}>
          <span className={css.reviewMeterReading}>{t('review.meterUsed')}</span>
          <span className={css.reviewMeterPercent}>{occupancy.percent}%</span>
          <span className={`${css.reviewMeterFigures} ${components.truncate}`}>
            {t('review.meterFigures', {
              used: formatTokens(occupancy.usedTokens),
              window: formatTokens(occupancy.contextWindow),
            })}
          </span>
        </div>
        <div className={css.reviewMeterBar} aria-hidden="true">
          {segments.map(segment => (
            <span
              key={segment.key}
              className={`${css.reviewMeterSegment}${segment.className !== undefined ? ` ${css[segment.className]}` : ''}`}
              style={{ width: `${segment.width}%` }}
            />
          ))}
        </div>
        {(() => {
          const breakdown = projections?.contextBreakdown
          if (breakdown === undefined) return null
          return (
            <div className={css.reviewMeterRows}>
              <span className={css.reviewMeterRow}>
                <span className={`${css.reviewMeterSwatch} ${css.meterSystem}`} aria-hidden="true" />
                <span className={`${css.reviewMeterLabel} ${components.truncate}`}>{t('review.meterSystem')}</span>
                <span className={css.reviewMeterValue}>~{formatTokens(breakdown.systemTokens)}</span>
              </span>
              <span className={css.reviewMeterRow}>
                <span className={`${css.reviewMeterSwatch} ${css.meterTools}`} aria-hidden="true" />
                <span className={`${css.reviewMeterLabel} ${components.truncate}`}>{t('review.meterTools')}</span>
                <span className={css.reviewMeterValue}>~{formatTokens(breakdown.toolsTokens)}</span>
              </span>
              <span className={css.reviewMeterRow}>
                <span className={`${css.reviewMeterSwatch} ${css.meterMessages}`} aria-hidden="true" />
                <span className={`${css.reviewMeterLabel} ${components.truncate}`}>{t('review.meterMessages')}</span>
                <span className={css.reviewMeterValue}>~{formatTokens(breakdown.messageTokens)}</span>
              </span>
            </div>
          )
        })()}
        {totalCumulative && total !== undefined && (
          <p className={css.reviewUsage}>
            {t('review.usageTotal')} · {t('review.usageInput', { n: formatTokens(total.inputTokens) })} · {t('review.usageOutput', { n: formatTokens(total.outputTokens) })}
            {total.cacheReadTokens !== undefined && ` · ${t('review.usageCacheRead', { n: formatTokens(total.cacheReadTokens) })}`}
            {total.cacheWriteTokens !== undefined && ` · ${t('review.usageCacheWrite', { n: formatTokens(total.cacheWriteTokens) })}`}
            {(() => {
              // Prompt-cache hit rate rides the same cumulative buckets (read
              // over all input); a zero denominator hides the fragment instead
              // of printing NaN — absence is key absence, never a fake figure.
              const hit = total.cacheReadTokens !== undefined
                ? cacheHitRate(total.cacheReadTokens, total.inputTokens)
                : undefined
              return hit !== undefined ? ` · ${t('review.usageHitRate', { p: hit })}` : null
            })()}
          </p>
        )}
        {(() => {
          const stats = projections?.sessionStats
          if (stats === undefined) return null
          // TTFT average and decode rate ride the same whole-log figures;
          // either unmeasurable hides its own fragment (never `0 tok/s`).
          const ttft = stats.ttftSteps > 0
            ? t('review.statsTtft', { d: formatDuration(stats.ttftMs / stats.ttftSteps) })
            : undefined
          const tps = formatTps(stats.decodeTokens, stats.decodeMs)
          return (
            <p className={css.reviewUsage}>
              {t('review.statsTurns', { turns: String(stats.turns), steps: String(stats.steps) })}
              {(stats.llmMs > 0 || stats.toolMs > 0) && ` · ${t('review.statsTime', {
                llm: formatDuration(stats.llmMs),
                tool: formatDuration(stats.toolMs),
              })}`}
              {ttft !== undefined && ` · ${ttft}`}
              {tps !== undefined && ` · ${t('review.usageTps', { n: tps })}`}
            </p>
          )
        })()}
      </div>
    )
  }
  if (total !== undefined) {
    if (totalCumulative) {
      return (
        <p className={css.reviewUsage}>
          {t('review.usageTotal')} · {t('review.usageInput', { n: formatTokens(total.inputTokens) })} · {t('review.usageOutput', { n: formatTokens(total.outputTokens) })}
          {total.cacheReadTokens !== undefined && ` · ${t('review.usageCacheRead', { n: formatTokens(total.cacheReadTokens) })}`}
          {total.cacheWriteTokens !== undefined && ` · ${t('review.usageCacheWrite', { n: formatTokens(total.cacheWriteTokens) })}`}
        </p>
      )
    }
    return (
      <p className={css.reviewUsage}>
        {t('review.usage')}：
        {t('review.usageInput', { n: String(total.inputTokens) })} · {t('review.usageOutput', { n: String(total.outputTokens) })}
        {total.cacheReadTokens !== undefined && ` · ${t('review.usageCacheRead', { n: String(total.cacheReadTokens) })}`}
        {total.cacheWriteTokens !== undefined && ` · ${t('review.usageCacheWrite', { n: String(total.cacheWriteTokens) })}`}
        {total.reasoningTokens !== undefined && ` · ${t('review.usageReasoning', { n: String(total.reasoningTokens) })}`}
      </p>
    )
  }
  return null
}

/**
 * The live session-config editor: model / reasoning effort / permission of
 * any native session, straight from the native APIs (the same sources the
 * harness's own selectors read). Permission applies through the native
 * `/permission` command registry — never a model turn. Self-contained: it
 * loads the model directory on mount and refreshes after every change; the
 * caller may bump `reloadKey` to force a re-read.
 */
export function SessionConfigEditor({ sessionId, controller, onChanged, reloadKey }: {
  sessionId: string
  controller: BoardController
  /** Fired after a successful change (the caller refreshes its transcript). */
  onChanged?: () => void
  /** A value whose change forces a full re-read of the model directory. */
  reloadKey?: unknown
}) {
  const sessionConfig = controller.sessionConfig()
  const catalog = controller.runCatalog()
  const [sessionModels, setSessionModels] = useState<{ current: SessionModelChoice; groups: readonly SessionModelGroup[] } | undefined>(undefined)
  /** Roster rows resolve the Host's stable preset id to the user's chosen name. */
  const [agentPresetRows, setAgentPresetRows] = useState<readonly AgentPresetLabelSource[]>([])
  // THREE states, never two: "still loading" and "the read failed" are
  // different facts, and showing the first as the red error line is how a
  // slow phone link read as a broken session (「会话经常加载不了」).
  const [configFailed, setConfigFailed] = useState(false)
  const [configBusy, setConfigBusy] = useState(false)
  const [configMessage, setConfigMessage] = useState<string | undefined>(undefined)
  /**
   * The session's LIVE permission value — read from the host's own
   * `permissions` projection, which is the value the harness's permission
   * selector displays. `undefined` = not read yet, `null` = the host does not
   * serve it.
   *
   * TWO sources can only disagree: the `permissions` block riding a history page
   * (a snapshot of past EVENTS — and `/permission` never opens a turn, so that
   * copy is frozen at whatever it said before the user changed anything) plus a
   * component-local optimistic `chosen` that dies on remount, arbitrated by an
   * effect that reads a projection value of '' as "no information" — and that is
   * how a panel shows 「默认」 over a session the user has just set. So: ONE value,
   * from ONE read, and the panel says so when it cannot read it.
   *
   * The CHOICES are a separate fact and come from where the host keeps them —
   * the permission-preset catalog — exactly as the harness's own selector joins
   * the two. The projection carries the value alone.
   */
  const [permissionValue, setPermissionValue] = useState<string | null | undefined>(undefined)
  const [permissionOptions, setPermissionOptions] = useState<readonly { id: string; name?: string; description?: string }[]>([])
  // Alive guard: every async handler (panel reload, model/effort/permission
  // applies) must not touch state after the panel unmounted — the panel can
  // close while a read/apply is still in flight, and a late `.then` must
  // not repaint a dead surface.
  const aliveRef = useRef(true)
  useEffect(() => () => { aliveRef.current = false }, [])
  // The retry nonce both live reads watch (a failure bumps it, never a
  // boolean-per-source pair).
  const [retryNonce, setRetryNonce] = useState(0)

  /** Re-read the LIVE permission value. */
  const readPermission = useCallback((): void => {
    if (sessionConfig === undefined) return
    void sessionConfig.readPermission(sessionId).then(result => {
      if (!aliveRef.current) return
      setPermissionValue(result ?? null)
    })
  }, [sessionConfig, sessionId])

  // On open, and whenever the caller forces a re-read: the value is a current
  // fact, so it is READ, never inherited from a stale render.
  useEffect(() => { readPermission() }, [readPermission, reloadKey, retryNonce])

  // The CHOICES, from the deployment's native preset catalog (the host keeps
  // them apart from the projection on purpose: the table is deployment-wide,
  // the value is per-session). Same join the harness's own selector makes.
  useEffect(() => {
    if (catalog === undefined) return
    let alive = true
    void (async () => {
      const [presets, permissions] = await Promise.all([
        catalog.listAgentPresets(),
        catalog.listPermissions(),
      ])
      if (!alive) return
      setAgentPresetRows(presets)
      setPermissionOptions(permissions ?? [])
    })()
    return () => { alive = false }
  }, [catalog])

  /** Re-read the live session panel (model selection + directory). */
  const reloadPanel = useCallback((): void => {
    if (sessionConfig === undefined) return
    void sessionConfig.readModels(sessionId).then(result => {
      if (!aliveRef.current) return
      if (result === undefined) setConfigFailed(true)
      else {
        setConfigFailed(false)
        setSessionModels(result)
      }
    })
  }, [sessionConfig, sessionId])

  // Load on open + whenever the caller forces a re-read (+ the retry nonce).
  useEffect(() => { reloadPanel() }, [reloadPanel, reloadKey, retryNonce])

  // SELF-HEALING failure: a transient read failure (flaky phone link, the
  // host mid-restart) retries once after a beat on its own, and again when
  // the tab returns to the foreground — a failure is never a dead end the
  // user must discover and punch through manually. One retry in flight.
  const pendingRetryRef = useRef(false)
  const failedRef = useRef(false)
  failedRef.current = configFailed
  const scheduleRetry = useCallback((): void => {
    if (pendingRetryRef.current) return
    pendingRetryRef.current = true
    setTimeout(() => {
      pendingRetryRef.current = false
      if (aliveRef.current) setRetryNonce(value => value + 1)
    }, 2_000)
  }, [])
  useEffect(() => {
    const onVisibility = (): void => { if (!document.hidden && failedRef.current) scheduleRetry() }
    document.addEventListener('visibilitychange', onVisibility)
    return () => { document.removeEventListener('visibilitychange', onVisibility) }
  }, [scheduleRetry])
  useEffect(() => { if (configFailed) scheduleRetry() }, [configFailed, scheduleRetry])

  /** Apply a new model selection to the session. */
  const applyModel = (key: string): void => {
    if (sessionConfig === undefined || sessionModels === undefined) return
    const parts = modelSelectParts(key)
    if (parts === undefined) return
    const { provider, model } = parts
    const group = sessionModels.groups.find(candidate => candidate.provider === provider)
    const row = group?.models.find(candidate => candidate.id === model)
    const effort = row?.reasoning?.defaultEffort
    setConfigBusy(true)
    setConfigMessage(undefined)
    void sessionConfig.selectModel(sessionId, { provider, model, ...effort !== undefined ? { reasoningEffort: effort } : {} }).then(result => {
      if (!aliveRef.current) return
      setConfigBusy(false)
      setConfigMessage(result.ok ? t('review.configApplied') : result.error)
      if (result.ok) {
        reloadPanel()
        onChanged?.()
      }
    })
  }

  /** Apply a reasoning effort to the current model selection. */
  const applyEffort = (effort: string): void => {
    if (sessionConfig === undefined || sessionModels === undefined) return
    const selection = sessionModels.current
    setConfigBusy(true)
    setConfigMessage(undefined)
    void sessionConfig.selectModel(sessionId, {
      provider: selection.provider,
      model: selection.model,
      ...effort !== '' ? { reasoningEffort: effort } : {},
    }).then(result => {
      if (!aliveRef.current) return
      setConfigBusy(false)
      setConfigMessage(result.ok ? t('review.configApplied') : result.error)
      if (result.ok) {
        reloadPanel()
        onChanged?.()
      }
    })
  }

  /** Apply a permission preset to the session. */
  const applyPermission = (value: string): void => {
    if (sessionConfig === undefined) return
    setConfigBusy(true)
    setConfigMessage(undefined)
    void sessionConfig.setPermission(sessionId, value).then(result => {
      if (!aliveRef.current) return
      setConfigBusy(false)
      setConfigMessage(result.ok ? t('review.configApplied') : result.error)
      // Re-read the live value either way: on success it is the new one, and
      // on a refusal it is the old one — which is exactly what the select must
      // show. There is no optimistic local copy to drop, because there is no
      // second truth to keep in step with.
      readPermission()
      if (result.ok) onChanged?.()
    })
  }

  if (sessionConfig === undefined) return null

  return (
    <section className={css.reviewConfig}>
      <span className={css.reviewConfigTitle}>{t('review.config')}</span>
      {sessionModels === undefined ? (
        configFailed ? (
          // Failed, and the automatic retry did not land: say so honestly and
          // hand the user the retry — never a red line on a still-loading read.
          <span className={css.reviewConfigFailed}>
            <span className={css.reviewConfigUnavailable}>{t('review.configUnavailable')}</span>
            <Button size="sm" onClick={scheduleRetry}>{t('review.retry')}</Button>
          </span>
        ) : (
          <span className={css.reviewConfigLoading}>{t('review.configLoading')}</span>
        )
      ) : (
        <div className={css.reviewConfigGrid}>
          {/* The session's real composition first, matching the task detail's
              run-config field order: workspace → agent → model → effort →
              permission. Read-only rows are plain value boxes (no dropdown
              affordance); the selects apply instantly. */}
          <SessionFacts info={controller.sessionInfo(sessionId)} agentPresets={agentPresetRows} />
          <span className={css.reviewConfigRow}>
            <span className={`${css.reviewConfigLabel} ${components.truncate}`}>{t('review.model')}</span>
            <span className={css.selectWrap}>
              <Select
                value={modelSelectValue(sessionModels.current.provider, sessionModels.current.model)}
                disabled={configBusy}
                onChange={event => { applyModel(event.target.value) }}
              >
                {sessionModels.groups.map(group => (
                  <optgroup key={group.provider} label={group.provider}>
                    {group.models.map(model => (
                      <option key={modelSelectValue(group.provider, model.id)} value={modelSelectValue(group.provider, model.id)}>
                        {model.name ?? model.id}
                      </option>
                    ))}
                  </optgroup>
                ))}
              </Select>
            </span>
          </span>
          {(() => {
            const group = sessionModels.groups.find(candidate => candidate.provider === sessionModels.current.provider)
            const row = group?.models.find(candidate => candidate.id === sessionModels.current.model)
            const efforts = row?.reasoning?.efforts ?? []
            if (efforts.length === 0) return null
            return (
              <span className={css.reviewConfigRow}>
                <span className={`${css.reviewConfigLabel} ${components.truncate}`}>{t('review.effort')}</span>
                <span className={css.selectWrap}>
                  <Select
                    value={sessionModels.current.reasoningEffort ?? ''}
                    disabled={configBusy}
                    onChange={event => { applyEffort(event.target.value) }}
                  >
                    <option value="">{t('review.effortDefault')}</option>
                    {efforts.map(effort => (
                      <option key={effort.id} value={effort.id}>{effort.name ?? effort.id}</option>
                    ))}
                  </Select>
                </span>
              </span>
            )
          })()}
          {permissionValue === undefined ? null : permissionValue === null || permissionOptions.length === 0 ? (
            /* No live read, a host that does not serve the projection, or no
               catalog to choose from. Say so: a select sitting on a fabricated
               「默认」 is a lie the user cannot detect, and the whole point of
               the row is to state what the session IS doing. */
            <span className={css.reviewConfigRow}>
              <span className={`${css.reviewConfigLabel} ${components.truncate}`}>{t('review.permission')}</span>
              <span className={css.reviewConfigUnavailable}>{t('review.permissionUnreadable')}</span>
            </span>
          ) : (
            /* The session's real value, read live; the choices from the
               deployment's catalog. There is deliberately NO empty-value
               option: a session always HAS a permission, `/permission` has no
               "unset" verb, and the old 「默认（会话默认权限）」 entry silently
               did nothing when chosen. (「默认」 still belongs in the run-config
               form, where it means "don't write a preset for the next run" —
               a different fact, in a different place.) A value the catalog does
               not list is still shown, under its own id, rather than being
               silently rewritten to whatever the first option happens to be. */
            <span className={css.reviewConfigRow}>
              <span className={css.reviewConfigLabel}>{t('review.permission')}</span>
              <span className={css.selectWrap}>
                <Select
                  value={permissionValue}
                  disabled={configBusy}
                  onChange={event => { applyPermission(event.target.value) }}
                >
                  {permissionOptions.some(option => option.id === permissionValue)
                    ? null
                    : <option value={permissionValue}>{permissionLabel(permissionValue, permissionValue)}</option>}
                  {permissionOptions.map(option => (
                    <option key={option.id} value={option.id}>{permissionLabel(option.id, option.name)}</option>
                  ))}
                </Select>
              </span>
            </span>
          )}
        </div>
      )}
      {configMessage !== undefined && <span className={css.reviewConfigMessage}>{configMessage}</span>}
    </section>
  )
}

/**
 * The rail head BODY: context meter + live config editor + session facts,
 * composed in the order every session panel shows them. SessionRail renders
 * it inside the shared Disclosure (the fold + chevron grammar) within the
 * rail's single scroll body; callers pass what they read from their
 * transcript hook (projections via onResult, folded turns). The permission
 * switcher's projection mapping is derived HERE — one source for every panel
 * (a caller-level mapping is how the linked panel lost it).
 */
export function SessionRailHead({ sessionId, controller, projections, turns, onChanged, reloadKey }: {
  sessionId: string | undefined
  controller: BoardController
  projections: TranscriptProjectionsShape | undefined
  /** The folded turns (token-accounting fallback for the meter). */
  turns: readonly TranscriptTurn[] | undefined
  onChanged?: () => void
  reloadKey?: unknown
}) {
  // Without a session there is nothing to show (the caller keeps its rail
  // empty, exactly like the gating on sessionId).
  if (sessionId === undefined) return null
  // The permission switcher is NOT mapped from these projections: it reads the
  // session's live `permissions` projection itself (see SessionConfigEditor).
  // A per-session setting is a current fact, and the history-page copy of it
  // never refreshes — sitting on that frozen copy shows 「默认」 over a session
  // the user has just re-permissioned.
  return (
    <>
      <ContextMeterPanel projections={projections} usage={sumUsage(turns ?? [])} />
      <SessionConfigEditor
        sessionId={sessionId}
        controller={controller}
        onChanged={onChanged}
        reloadKey={reloadKey}
      />
    </>
  )
}

/**
 * THE session rail — the one composition every session panel renders (the
 * execution review page and the linked-session panel share it verbatim), and
 * THE height contract that ends the squeeze-and-clip family of bugs.
 *
 * It hands its caller TWO blocks, never four:
 *
 *   [ folds: live state row → collapsible CONFIG head → collapsible COMMENTS ]
 *   [ the caller's pinned composer                                           ]
 *
 * Desktop geometry: the rail is a flex column — the folds block absorbs the
 * height (its comments region owns the one scroll box inside it) and the
 * composer is `flex: none` below, so nothing can push the send box away.
 *
 * Narrow geometry (the panel's own container query): the rail box steps aside
 * (`display: contents`) and the panel becomes a THREE-ROW grid —
 * `folds / transcript / composer`. That is the whole fix for 「上下文一多就把
 * 评论和留言按钮全部截断」:
 *   - the folds block is capped (a fraction of the panel) and bounds a fully
 *     rendered head, so an expanded config can never eat the screen;
 *   - the comments box owns its capped scroll at every width (one grammar —
 *     滑到最新 drives it, desktop and phone);
 *   - the transcript owns the flexible middle row and always keeps room;
 *   - the composer is its own grid row at the panel's bottom edge — not the
 *     last item in someone else's scroll content (which is exactly how it used
 *     to end up below the fold, unreachable).
 * Because the folds block is capped and the comments box scrolls inside
 * its own cap, opening one fold never reflows the other, and 滑到最新
 * drives the box that actually holds the comments — at every width.
 *
 * Callers pass data and their send semantics; the grammar, the folds and the
 * hint line live here exactly once — no panel can drift again.
 */
export function SessionRail({ stateChip, updatedAt, sessionId, controller, projections, turns, onChanged, reloadKey, task, thread, onCancelComment, interaction, shellWaiting, composer }: {
  /** The live state row (chip + updated time); absent hides the whole row. */
  stateChip?: { kind: ChipKind; label: string; spinner?: boolean }
  updatedAt?: string
  sessionId: string | undefined
  controller: BoardController
  projections: TranscriptProjectionsShape | undefined
  turns: readonly TranscriptTurn[] | undefined
  onChanged?: () => void
  reloadKey?: unknown
  task: TaskRecord
  thread: readonly CommentView[]
  onCancelComment: (roundId: string) => boolean
  /** The pending native question (plan confirm / ask); absent hides the card. */
  interaction: WireQuestion | undefined
  /** Proven wait without parsed content (carrier-shape backstop): renders the
   *  honest shell card instead of blank nothing. Absent with `interaction`. */
  shellWaiting?: 'plan-review' | 'question'
  /** The pinned composer (the panel's send semantics stay in the caller). */
  composer: ReactNode
}) {
  // The comment thread follows its latest round through the SAME mechanism as
  // the transcript (resolved scroller + capture listener + pinning). The ROOT
  // is the comments box itself at every width — 滑到最新 always drives the
  // region that actually holds the comments.
  const commentsScrollRef = useRef<HTMLDivElement | null>(null)
  const [commentsAtBottom, setCommentsAtBottom] = useState(true)
  // Both folds start with the config head FOLDED on a phone: the
  // conversation and the send box are the first screen, while the comments
  // fold starts OPEN on desktop and FOLDED on a phone (one grammar —
  // collapsible on tap at every width). A wide rail absorbs the config
  // (two-column config grid), so it starts open there. The signal is the PANEL's own width (the same
  // surface the CSS container query measures, via `useSurfaceNarrow`) — NOT the
  // viewport: a mid-size window with the shell sidebar open already renders the
  // stacked panel while the viewport still says "wide", and a default that
  // followed the viewport would disagree with what the user is looking at.
  const [narrowPanel, foldsRef] = useSurfaceNarrow('[data-dsh-taskboard-panel]', bandNarrowMax('sessionPanel', 600))
  const [headOpen, setHeadOpen] = useState(!narrowPanel)
  // The comments default follows the PANEL width (same surface the CSS
  // queries): open on desktop (the thread is the first screen beside the
  // conversation), folded on a phone (an open thread would bury the
  // conversation + context — the tap toggles either way, one grammar).
  const [commentsOpen, setCommentsOpen] = useState(!narrowPanel)
  const threadFingerprint = thread.map(view => `${view.round.id}:${view.state}`).join('|')
  // Content card OR honest shell: either one means the session is awaiting
  // the user and owns every force-open/follow behavior below — one boolean,
  // never two parallel conditions to drift apart.
  const awaiting = interaction !== undefined || shellWaiting !== undefined
  const { measure: onCommentsScroll, jumpToBottom: jumpComments } = useFollowScroll(
    commentsScrollRef, commentsAtBottom, setCommentsAtBottom, threadFingerprint,
    /* Remount signal: folding the comments unmounts .commentsScroll; the fold
       state flips back on re-expand, so the observer + follow effects re-bind
       to the NEW element — without it, a fold→expand loop loses bottom-follow
       and the 滑到最新 button. */
    commentsOpen || awaiting,
  )
  // OPEN / NEW ASK = LATEST — one grammar at every width: opening the fold
  // (a manual tap, or a pending question force-opening it) lands on the
  // newest comment, and a new ask pins again so the question is always the
  // thing in view (the default-open mount is pinned by the follow effect
  // itself, atBottom starts true). Answering never moves the reader: only
  // open edges and a live ask trigger, so scrolling up while reading stays
  // put. The pin scrolls the comment box itself — the fold head lives
  // outside that box, so it can never be pushed off-screen by it.
  const openEdgeRef = useRef(commentsOpen || awaiting)
  useEffect(() => {
    const open = commentsOpen || awaiting
    const opened = open && !openEdgeRef.current
    openEdgeRef.current = open
    if (awaiting || opened) jumpComments()
  }, [commentsOpen, awaiting, interaction?.rpcId, shellWaiting, jumpComments])
  // The collapsed head still says something: the live context occupancy
  // rides the disclosure summary (zero-omission quietness, same as every
  // other summary — no projection, no line).
  const occupancy = contextOccupancy(projections?.contextPressure)
  return (
    <>
      <div className={css.sessionRailFolds} ref={foldsRef}>
        {stateChip !== undefined && updatedAt !== undefined && (
          <div className={css.sessionFacts}>
            <Chip
              kind={stateChip.kind}
              icon={stateChip.spinner === true ? <span className={css.spinner} aria-hidden="true" /> : undefined}
            >
              {stateChip.label}
            </Chip>
            <span className={css.sessionFactTime}>{t('detail.sessionUpdated')} {updatedAt}</span>
          </div>
        )}
        {/* The head (context meter + live run config): ONE Disclosure fold.
            OPENED = rendered FULLY — the body carries no scrollbar of its own
            (a config cut at the model row WITH its own slider is exactly the
            「显示不全」 disease). On a phone the FOLDS BLOCK is the scroller,
            so a fully-rendered config stays reachable without stealing the
            transcript's or the composer's room. */}
        <div className={css.sessionRailHead}>
          <Disclosure
            className={css.railHeadSection}
            headerClassName={css.railDisclosure}
            title={t('review.railHeadTitle')}
            summary={occupancy !== undefined ? `${occupancy.percent}%` : undefined}
            open={headOpen}
            onToggle={() => { setHeadOpen(!headOpen) }}
          >
            <SessionRailHead
              sessionId={sessionId}
              controller={controller}
              projections={projections}
              turns={turns}
              onChanged={onChanged}
              reloadKey={reloadKey}
            />
          </Disclosure>
        </div>
        {/* The comments: ONE Disclosure fold, open by default on desktop and
            folded by default on a phone (an open thread would bury the
            conversation + context there; the tap toggles either way).
            OPENED = the thread box with its own capped scroll (the desktop
            grammar, both widths — 滑到最新 drives this box, the follow hook
            resolves the real scroller). A pending interaction FORCE-opens
            it — the InteractionCard carries the answer affordance (in place
            through the official carrier, navigate-to-answer only when that
            carrier exposes no action), so a collapsed
            fold can never hide it; the summary names that wait too. */}
        <div className={css.sessionRailComments} data-open={commentsOpen || awaiting}>
          <Disclosure
            className={css.railCommentsSection}
            headerClassName={css.railCommentsDisclosure}
            title={t('review.comments')}
            summary={awaiting ? t('review.waiting') : String(thread.length)}
            open={commentsOpen || awaiting}
            /* While the card forces the fold open, the row is INERT: flipping
               the hidden flag anyway made the tap look dead (aria-expanded
               stayed true) and then silently collapsed the thread the moment
               the question was answered — a state that contradicts what the
               user just saw. */
            onToggle={() => { if (!awaiting) setCommentsOpen(!commentsOpen) }}
          >
            <div className={css.commentsScroll} ref={commentsScrollRef} onScroll={onCommentsScroll}>
              <CommentsThread task={task} views={thread} onCancel={onCancelComment} />
              {awaiting && sessionId !== undefined && (
                <InteractionCard
                  key={interaction !== undefined ? interaction.rpcId : `shell-${sessionId}`}
                  question={interaction}
                  shellWaiting={interaction === undefined ? shellWaiting : undefined}
                  sessionId={sessionId}
                  controller={controller}
                />
              )}
              <JumpToLatest atBottom={commentsAtBottom} onJump={jumpComments} />
            </div>
          </Disclosure>
        </div>
      </div>
      {composer}
    </>
  )
}

/**
 * The pinned composer of the rail — one grammar for every session panel:
 * prompt input (slash autocomplete) + attachment strip + send-mode switch
 * (排队/插话) + the primary send button + ONE quiet line under it.
 *
 * The explanation line belongs to the COMPOSER, not to the comment thread:
 * what 排队/插话 do, and why sending is refused (a finished task, a gone
 * session), is information a touch user must be able to reach — it can never
 * live only in a foldable explanation or a hover-only tooltip. Draft / steer
 * here (the per-session draft slot, shared across panels); the caller
 * supplies only the send semantics:
 *   - onDrive(text, attachments) schedules a session-anchored comment round
 *     (true = saved, the draft clears) — / commands route through the native
 *     registry; whatever the message carries rides the round and goes out WITH
 *     it when the lane frees (排队 means wait, with or without attachments);
 *   - onSteer(text, attachments) delivers the same message straight to the
 *     session now. ONE ledger, two dispositions: the send mode is the user's
 *     toggle — attachments never force steer, and neither mode can lose them.
 */

export function SessionComposer({ controller, taskId, sessionId, placeholder, disabled, hint, onDrive, onSteer }: {
  controller: BoardController
  taskId: string
  sessionId: string | undefined
  placeholder: string
  /** Extra rejection state (done task / gone session): blocks the send. */
  disabled?: boolean
  /** The composer's own explanation (blocking reason, or the drive hint). */
  hint?: string
  onDrive: (text: string, attachments: readonly DraftAttachment[]) => boolean
  onSteer: (text: string, attachments: readonly DraftAttachment[]) => Promise<boolean>
}) {
  const storeKey = sessionId === undefined ? undefined : commentDraftKey(taskId, sessionId)
  // Restored once per mount (text via useState, attachments through the hook's
  // setter — the hook owns the ledger, so restoration goes through it, never
  // around it).
  const [restored] = useState<CommentDraftSnapshot>(() =>
    decodeCommentDraft(storeKey !== undefined ? draftStore.get(storeKey) : undefined))
  const [draft, setDraft] = useState<string>(restored.text)
  const [steer, setSteer] = useState(false)
  /* 待插入的引用。它是**一次性指令**而不是草稿的一部分：插进去之后立刻清空，否则下一次
     重渲染会把同一段引用再插一遍（「粘了两遍」）。 */
  const [pendingQuote, setPendingQuote] = useState<string | undefined>(undefined)
  /* 「引用」手势的裁决范围：会话面板的根。向上找我们自己打的那枚属性——不读宿主的 DOM
     或类名（契约表两条纪律），而它一定存在：这个输入框只可能挂在面板里。 */
  const composerRef = useRef<HTMLDivElement | null>(null)
  const [quoteHost, setQuoteHost] = useState<HTMLElement | null>(null)
  useEffect(() => {
    setQuoteHost(composerRef.current?.closest<HTMLElement>('[data-dsh-taskboard-panel]') ?? null)
  }, [])
  // The attachment ledger is the SHARED hook: pick / drop-anywhere / paste,
  // image compression, admission into the official store, count caps and every
  // rejection said out loud. The composer container carries the drop/paste
  // props so a desktop user can drop a file or paste a screenshot anywhere on
  // it, not just on the thin strip. No session is needed to attach: the bytes
  // go to the store now, and the send materializes them for whichever session
  // the message actually leaves through.
  const attachments = useComposerAttachments({
    budget: COMMENT_IMAGE_BUDGET,
    maxImages: MAX_COMMENT_IMAGES,
    ...controller.attachmentsAvailable() ? { admit: input => controller.admitAttachment(input) } : {},
  })
  const { attachments: attached, setAttachments, addFiles, addEncoded, dropProps } = attachments
  // A failed SEND is distinct from a failed INTAKE; surface it right under
  // the composer (never a silent drop — the user must know their words and
  // attachments did not go out).
  const [sendError, setSendError] = useState<string | undefined>(undefined)
  // ONE persist grammar: every text/attachment change lands in the draft
  // store. Attachments persist as refs, so a draft that comes back comes back
  // whole — text, pictures and files alike.
  useEffect(() => {
    if (storeKey === undefined) return
    draftStore.set(storeKey, encodeCommentDraft(draft, attached))
  }, [storeKey, draft, attached])
  // Restore-once: refs the draft kept come back as chips, and the v1 leftovers
  // (pictures the old grammar stored as bytes) are admitted right here — one
  // round trip, then they are ordinary attachments again.
  useEffect(() => {
    if (restored.attachments.length > 0) setAttachments(restored.attachments)
    if (restored.legacyImages.length > 0) void addEncoded(restored.legacyImages)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])
  const clear = (): void => {
    setDraft('')
    setAttachments([])
    setSendError(undefined)
    if (storeKey !== undefined) draftStore.clear(storeKey)
  }
  const submit = (): void => {
    const text = draft.trim()
    if ((text === '' && attached.length === 0) || disabled === true) return
    // ONE clear grammar for every send mode: the draft leaves the composer at
    // submit, so a repeated click can never double-send (queue cleared right
    // away; steer only after the host answered — a quick second click would
    // have sent the same message twice). A rejection restores the draft so
    // the user keeps their words to retry.
    const restore = (): void => {
      setDraft(text)
      setAttachments(attached)
      // No direct store write: the persist effect re-saves the full envelope
      // (text + refs) from the restored state — a raw-text write here would
      // clobber the attachments out of the draft.
    }
    clear()
    // The send mode is the user's toggle — NEVER overridden by the presence of
    // attachments (that was the bug: a queued picture jumped the queue and sent
    // immediately while the session was still running).
    if (steer) {
      const sent = onSteer(text, attached)
      // A REFUSAL MUST SPEAK, and this branch is why that sentence exists six
      // lines below: a draft that comes back silently leaves a reader whose
      // words reappear in the box seeing NOTHING AT ALL — which is the whole
      // 「按了没反应」 this rule exists to prevent, six lines further down and one
      // branch away.
      setSendError(undefined)
      void sent.then(ok => {
        if (ok) return
        restore()
        setSendError(t('review.sendNotSent'))
      })
      return
    }
    // 排队: the dispatcher injects this round (text + attachments) when the
    // session's lane is free — it waits behind the running turn, never jumps it.
    // A refusal must SPEAK: restoring the draft silently is how "点了没反应"
    // happens (the words came back, so the user sees nothing at all).
    setSendError(undefined)
    if (!onDrive(text, attached)) {
      restore()
      setSendError(t('review.sendNotSent'))
    }
  }
  // The busy line names the IN-FLIGHT intake (hook's busyKind), never the
  // settled ledger — a file being admitted is not in the ledger yet.
  const busyLabel = attachments.busy ? attachBusyLabel(attachments.busyKind) : undefined
  return (
    <div className={css.reviewComposer} {...dropProps} ref={composerRef}>
      <PromptInput
        value={draft}
        onChange={next => { setDraft(next) }}
        placeholder={placeholder}
        rows={3}
        controller={controller}
        sessionId={sessionId}
        quote={pendingQuote}
        onQuoteConsumed={() => { setPendingQuote(undefined) }}
      />
      {/* 引用手势挂在这里：它自己裁决选区（落在面板里、且不在输入框里），只在有选中
          文字时浮出那一枚按钮。位置为零尺寸的占位组件，不占版面。 */}
      <QuoteSelection host={quoteHost} onQuote={quote => { setPendingQuote(quote) }} />
      {/* The attachment strip is its OWN row between the input and the action
          row: chips wrap there and can never grow the action row, so the send
          button stays visible + tappable no matter how many files are
          picked (the "选图后发送按钮被挤没" bug). */}
      <AttachmentStrip
        attachments={attached}
        onAdd={files => { void addFiles(files) }}
        onRemove={id => { setAttachments(attached.filter(entry => entry.id !== id)) }}
        busy={attachments.busy}
        busyLabel={busyLabel}
        // SEND FAILURE FIRST. Sitting behind `attachments.error` would let an
        // admission error left over from a moment ago mask the reason a send was
        // refused — and the two answer different questions: one is 「the file did
        // not go up」, the other is 「your words did not go out」. The newest thing
        // that went wrong is the one the reader is looking at, so the refusal
        // leads and the older attachment problem waits its turn.
        error={sendError ?? attachments.error}
      />
      <div className={css.reviewComposerRow}>
        <SendModeToggle steer={steer} onChange={setSteer} />
        <Button
          variant="primary"
          disabled={(draft.trim() === '' && attached.length === 0) || disabled === true}
          onClick={submit}
        >
          {t('review.commentSend')}
        </Button>
      </div>
      {/* One quiet line, and it only ever says why SENDING IS REFUSED.
          The two send modes are already spelt out by the two buttons' own
          labels (「排队」/「插话」), so a line explaining them was a third
          copy of the same sentence. A refusal, on the other hand, has no
          other place to appear — and it lives HERE, outside any fold, because
          a touch user has no hover to discover it with. */}
      {hint !== undefined && <p className={css.detailHint}>{hint}</p>}
    </div>
  )
}